// Retire the former Chirpy offline worker, including for returning visitors.
// Keep this URL available so browsers with an old registration can update it.
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names.filter((name) => name.startsWith('chirpy-'))
        .map((name) => caches.delete(name))
    );
    // The existing app reloads on controllerchange, showing the current page.
    await self.clients.claim();
    await self.registration.unregister();
  })());
});
